<template><div class="page"><AppNav/><main class="content"><header class="title"><div><span class="eyebrow">COURSE RESOURCE HUB</span><h1>课程资料库</h1><p>把讲义、笔记、题单和可靠链接汇集在课程中，Agent 会优先检索这里的内容。</p></div><button class="primary" @click="dialog=true">＋ 发布资料</button></header><section class="course-tabs"><button v-for="course in courses" :key="course.id" :class="{active:selected===course.id}" @click="selected=course.id;loadResources()"><i :style="{background:course.color}"></i><b>{{course.name}}</b><span>{{course.resource_count}} 份资料</span></button></section><section class="toolbar panel"><el-input v-model="query" placeholder="搜索标题、标签或资料说明" clearable @input="loadResources"/><span>{{ resources.length }} 条结果</span></section><section class="resources"><article v-for="resource in resources" :key="resource.id" class="resource-card"><div class="file">{{icon(resource.type)}}</div><div><span>{{resource.course_name}} · {{resource.type}}</span><h2>{{resource.title}}</h2><p>{{resource.description || '发布者暂未填写说明。'}}</p><small>标签：{{resource.tags || '未标注'}} · {{resource.uploader_name || '课程管理员'}}</small></div><a v-if="resource.url" :href="resource.url" target="_blank">查看链接 ↗</a></article><div v-if="!resources.length" class="empty">暂时没有匹配资料。发布第一份课程资料吧。</div></section></main><el-dialog v-model="dialog" title="发布课程资料" width="500px"><el-form label-position="top"><el-form-item label="所属课程"><el-select v-model="form.course_id" style="width:100%"><el-option v-for="c in courses" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="资料标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="资料类型"><el-select v-model="form.type" style="width:100%"><el-option label="讲义 / 笔记" value="note"/><el-option label="练习题" value="exercise"/><el-option label="外部链接" value="link"/></el-select></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="标签（用逗号分隔）"><el-input v-model="form.tags" placeholder="如：链表，栈，期中复习"/></el-form-item><el-form-item label="可选链接"><el-input v-model="form.url" placeholder="https://…"/></el-form-item></el-form><template #footer><button class="primary" @click="publish">发布到资料库</button></template></el-dialog></div></template>
<script setup>import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import AppNav from'../components/AppNav.vue';import{api,post}from'../utils/api';const courses=ref([]),resources=ref([]),selected=ref(0),query=ref(''),dialog=ref(false),form=ref({course_id:null,title:'',type:'note',description:'',tags:'',url:''});const icon=t=>({note:'▤',exercise:'✎',link:'↗'}[t]||'▤');async function loadResources(){resources.value=await api(`/resources?course_id=${selected.value||''}&query=${encodeURIComponent(query.value)}`)}async function publish(){try{await post('/resources',form.value);dialog.value=false;form.value={course_id:selected.value,title:'',type:'note',description:'',tags:'',url:''};loadResources()}catch(e){ElMessage.error(e.message)}}onMounted(async()=>{try{courses.value=await api('/courses');selected.value=courses.value[0]?.id||0;form.value.course_id=selected.value;loadResources()}catch(e){ElMessage.error(e.message)}})</script>
<style scoped>.content{max-width:1120px;margin:auto;padding:36px 5vw}.title{display:flex;justify-content:space-between;align-items:end;gap:20px}.eyebrow{font-size:11px;color:#b26b4a;letter-spacing:1.3px;font-weight:800}.title h1{color:#623a2b;margin:5px 0;font-size:31px}.title p{color:#92776a;max-width:690px}.primary{border:0;border-radius:13px;background:#c96d42;color:white;padding:11px 15px;font-weight:700;cursor:pointer;white-space:nowrap}.course-tabs{display:flex;gap:10px;overflow:auto;margin:28px 0 16px}.course-tabs button{min-width:185px;text-align:left;padding:14px;border:1px solid #efdfd4;border-radius:17px;background:#fffdfa;color:#7e6154;cursor:pointer}.course-tabs button.active{background:#fff0e4;border-color:#e9bca6}.course-tabs i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px}.course-tabs span{display:block;margin:6px 0 0 15px;font-size:12px;color:#a78d80}.panel,.resource-card,.empty{background:#fffdfa;border:1px solid #f1e2d8;border-radius:21px;box-shadow:0 10px 30px #9f4c2b0d}.toolbar{display:flex;align-items:center;gap:16px;padding:11px 15px}.toolbar span{font-size:13px;color:#987d70;white-space:nowrap}.resources{display:grid;gap:12px;margin-top:16px}.resource-card{padding:18px;display:flex;gap:15px;align-items:flex-start}.file{width:44px;height:44px;display:grid;place-items:center;border-radius:15px;background:#fff0e4;color:#b95d38;font-size:22px}.resource-card div:nth-child(2){flex:1}.resource-card span,.resource-card small{font-size:12px;color:#a48475}.resource-card h2{font-size:17px;color:#634030;margin:5px 0}.resource-card p{color:#866d61;margin:0 0 7px;line-height:1.5}.resource-card a{color:#af5937;font-size:13px;text-decoration:none;padding:7px}.empty{padding:35px;text-align:center;color:#9c8173}@media(max-width:640px){.content{padding:20px}.title h1{font-size:26px}.title{align-items:start;flex-direction:column}.resource-card a{display:none}}</style>
